// ============================================================================
// Prepare — Code node (no credentials). FishPin knowledge base + a single
// batchEmbedContents request (all KB chunks + the user's question).
// KB content is drawn faithfully from the live site's source of truth:
// fishpin-web/lib/{site,faqs,features,comparison}.ts — keep in sync if the site changes.
// ============================================================================

const cfg = $('Config').first().json;
const wh = $('Chat Webhook').first().json;
const body = (wh && wh.body) ? wh.body : {};

const message = String(body.message || body.query || body.text || '').trim();
const sessionId = String(body.sessionId || body.session_id || 'anonymous').trim();

const KB = [
  { title: 'What is FishPin', text: 'FishPin is an offline marine navigation app built for Filipino fishermen. It combines offline marine maps, real-time GPS navigation, saved fishing hotspots, trail recording, weather and marine conditions, and an AI fish guide. The goal: everything you need to head out and come home safely, with no internet signal required. Tagline: marine navigation for Filipino fishermen.' },
  { title: 'Price and cost', text: 'FishPin costs 499 Philippine pesos (₱499), paid once on Google Play before you download. There is no subscription, no in-app purchases, no premium unlock, and no recurring fees. For comparison: Navionics is about ₱3,250 per year, Fishbrain Pro about ₱4,200 per year, and a Garmin chartplotter is roughly ₱8,000 to ₱30,000 in hardware.' },
  { title: 'Works offline without internet', text: 'Yes, FishPin works fully without internet. Once you download a region, it uses your phone\'s built-in GPS chip, which works without any signal, and renders the cached map tiles offline. It is offline-first and designed for life at sea, so no data plan is needed once you are out.' },
  { title: 'Supported devices and platform', text: 'FishPin is Android-first and runs on virtually any modern Android phone. iOS (iPhone) support is planned for later in the year. There is no special hardware required.' },
  { title: 'How to download and get FishPin', text: 'You can get FishPin on the Google Play Store at https://play.google.com/store/apps/details?id=com.fishpin.app. You pay ₱499 once on Google Play before downloading, and there are no further charges after that.' },
  { title: 'Privacy of your fishing spots', text: 'Your fishing spots stay private. Pins are stored on your phone in a private database tied to your account. They are never shared with other fishermen and never sold to anyone.' },
  { title: 'Why FishPin focuses on Filipino fishermen', text: 'FishPin is built specifically for Filipino fishermen because small-scale fishing in the Philippines is dominated by fishermen who cannot afford an ₱8,000 to ₱30,000 marine GPS device. FishPin is affordable and designed with Philippine species, local conditions, and an offline-first design.' },
  { title: 'Partnership, sponsorship and contributing', text: 'FishPin works with fishing cooperatives, LGUs (local government units), NGOs, and individual sponsors to put the app in more hands, including sponsoring devices and training for fishermen who cannot afford it. To help, sponsor, partner, or contribute, email fishpinsupport@gmail.com.' },
  { title: 'Real-time GPS, compass and speed', text: 'FishPin provides real-time GPS, a compass, and speed. It gives continuous GPS at 4 fixes per second (4 Hz), a true magnetic compass, and a live speed readout in knots, so every movement appears instantly with no laggy refresh.' },
  { title: 'Background trail recording', text: 'FishPin records your fishing trip trail in the background, even with the screen off, using a persistent foreground service. You can lock the phone to save battery and pick up exactly where you left off.' },
  { title: 'Save and re-follow paths', text: 'You can save full trips with distance, average speed, and duration, then pick any saved path later. FishPin overlays it on the map so you can re-follow and re-fish the same productive route.' },
  { title: 'Custom spot pinning', text: 'FishPin lets you mark hotspots with custom pins. Long-press anywhere on the map to drop a pin, choose from 8 colors and 8 marine icons (anchor, fish, palm, sailboat and more), and add a private note.' },
  { title: 'AI fish scanner', text: 'FishPin has an AI fish scanner. Snap a photo of your catch and the app uses AI to identify the species, suggest a size estimate, and link straight into the local fish guide.' },
  { title: 'Philippine fish species guide', text: 'FishPin includes a Philippine fish species guide: a searchable guide focused on species found in Philippine waters, with local names, seasons, baits, and notes. It works fully offline.' },
  { title: 'Weather and marine conditions', text: 'FishPin shows weather and marine conditions: an hourly Open-Meteo forecast tied to your current GPS spot (temperature, wind, visibility) plus wave height, wind direction, and current strength in plain language, so you know before leaving shore whether today is a go or a no-go.' },
  { title: 'Fishing score', text: 'FishPin\'s Fishing Score reads the live weather for your current spot (wind, pressure, temperature, visibility, and conditions) and turns it into a single 0 to 100 score, so one glance tells you whether to go fishing or stay in, with no guesswork and no wasted fuel.' },
  { title: 'Emergency SOS alert', text: 'FishPin has an Emergency SOS alert. In an emergency, tap SOS to broadcast your last known GPS position, boat name, and contact details to your trusted contacts and nearby rescue channels, even with limited signal.' },
  { title: 'Nautical charts with depth zones', text: 'FishPin includes nautical charts with depth zones: a nautical map layer with bathymetric depth contours, seamarks, and depth shading, powered by MapTiler Ocean and OpenSeaMap data.' },
  { title: 'Offline map downloads', text: 'You can download offline map regions before you sail. Pick any rectangle on the map and download street or satellite tiles to your phone. FishPin shows the estimated download size before you commit.' },
  { title: 'Route planning with ETA', text: 'FishPin offers route planning with ETA (estimated time of arrival). Tap any pin to start navigation and FishPin draws a heading line and shows live distance, bearing, and an ETA based on your current speed.' },
  { title: 'How FishPin compares to Navionics, Fishbrain and Garmin', text: 'Compared to alternatives, FishPin is ₱499 once with no subscription; Navionics is about ₱3,250 per year; Fishbrain about ₱4,200 per year; Garmin GPS is ₱8,000 to ₱30,000 in hardware. FishPin works fully offline, has AI fish identification, a Philippine species guide, nautical depth charts, offline map downloads, and emergency SOS, and runs on any Android phone with no special hardware. Over five years FishPin costs about ₱499 versus roughly ₱16,250 for Navionics or ₱21,000 for Fishbrain.' },
  { title: 'Contact and support', text: 'You can contact FishPin support by email at fishpinsupport@gmail.com. The website is https://www.fishpin.app and the app is on the Google Play Store.' },
];

// ---- Conversation memory: load recent history for this session ----
// Stored in the workflow's persistent static data, keyed by sessionId, with a
// TTL so old chats expire. Best-effort: never break the flow if it fails.
let history = [];
let summary = '';
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const now = Date.now();
  const ttlMs = Number(cfg.memoryTtlMin || 120) * 60000;
  for (const k of Object.keys(sd.sessions)) {
    if (now - (sd.sessions[k].updated || 0) > ttlMs) delete sd.sessions[k];
  }
  const sess = sd.sessions[sessionId];
  history = (sess && Array.isArray(sess.turns)) ? sess.turns : [];
  summary = (sess && sess.summary) ? sess.summary : '';
} catch (e) {
  history = [];
  summary = '';
}

// Retrieval query = recent user turns + current message, so follow-ups like
// "does it work offline too?" still retrieve the right KB chunks.
const recentUser = history.filter((t) => t.role === 'user').slice(-2).map((t) => t.text);
const retrievalQuery = [...recentUser, message].join(' \n ').trim() || 'hello';

const model = 'models/' + cfg.embedModel;
const texts = KB.map((c) => c.title + '. ' + c.text);
texts.push(retrievalQuery);

const requests = texts.map((t) => ({ model, content: { parts: [{ text: String(t).slice(0, 8000) }] } }));

return [{ json: {
  message,
  sessionId,
  kb: KB.map((c) => ({ title: c.title, text: c.text })),
  history,
  summary,
  embedBody: { requests },
} }];

// ============================================================================
// Retrieve — Code node (no credentials). Ranks KB chunks by cosine similarity,
// injects the rolling memory note + recent turns, and builds a grounded,
// human-feeling Gemini chat request.
// ============================================================================

const cfg = $('Config').first().json;
const prep = $('Prepare').first().json;
const emb = $json; // batchEmbedContents response

const message = prep.message;
const kb = prep.kb || [];
const vecs = (emb && Array.isArray(emb.embeddings)) ? emb.embeddings : [];

const cosine = (a, b) => {
  let dot = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { dot += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return dot / (Math.sqrt(na) * Math.sqrt(nb) + 1e-9);
};

let context = '';
let score = 0;
let sources = [];

if (vecs.length >= kb.length + 1) {
  const qv = vecs[kb.length].values;
  const topK = Number(cfg.topK || 4);
  const ranked = kb
    .map((c, i) => ({ title: c.title, text: c.text, s: cosine(qv, vecs[i].values) }))
    .sort((a, b) => b.s - a.s);
  const top = ranked.slice(0, topK);
  score = top.length ? top[0].s : 0;
  sources = top.map((t) => t.title);
  context = top.map((c) => '[' + c.title + ']\n' + c.text).join('\n\n');
}

// ---- Persona: warm, intelligent, human — not a robotic FAQ ----
const persona = 'You are FishPin Assistant, a warm and genuinely helpful guide on the FishPin website. '
  + 'FishPin is an affordable, offline marine navigation Android app built for Filipino fishermen (₱499 one-time on Google Play). '
  + 'You care about fishermen — their safety at sea, their livelihood, and getting good value. You speak like a friendly, knowledgeable person '
  + '(think of a helpful kuya/ate), not like a machine. '
  + 'You can help with: what FishPin is, pricing, how to download, offline use, GPS / compass / speed, background trail recording, saved paths, '
  + 'custom spot pinning, the AI fish scanner, the Philippine species guide, weather & marine conditions, the fishing score, emergency SOS, '
  + 'nautical charts, offline map downloads, route planning / ETA, privacy, device support, comparisons with Navionics / Fishbrain / Garmin, and partnerships.';

const memoryNote = prep.summary
  ? '\n\nMEMORY NOTE — durable facts from earlier in this same conversation (treat as true and use naturally):\n' + prep.summary
  : '';

const style = '\n\nHOW TO TALK (be human and intelligent):\n'
  + '- Be warm, natural, and personable. Vary your wording; never sound canned or repeat the same sentences.\n'
  + '- Once you know the user\'s name, use it occasionally and naturally. Mirror their language and tone.\n'
  + '- Show genuine empathy for their situation (safety at sea, budget, long days fishing).\n'
  + '- REASON about what they really need: connect FishPin features to their specific situation. '
  + 'E.g. if they fish at night or far out, naturally highlight SOS, trail recording, or offline maps.\n'
  + '- If a question is ambiguous, ask one short, friendly clarifying question instead of guessing.\n'
  + '- For multi-part questions, address each part. Keep replies focused (usually 2-5 sentences) — helpful, not a wall of text.\n'
  + '- Never say "as an AI" or dismiss yourself as "just a bot". Be confident and personable.';

const rules = '\n\nIMPORTANT RULES:\n'
  + '1. FACTS: For concrete FishPin facts (prices, features, platforms, dates, policies) use ONLY the CONTEXT below. Never invent or guess them. You MAY reason, empathize, and make natural suggestions around those facts.\n'
  + '2. MEMORY: Use the MEMORY NOTE and the conversation history. Remember the user\'s name, location, boat, and what they asked. If they ask whether you remember them or what they told you, recall it confidently. NEVER claim you cannot remember things from this conversation.\n'
  + '3. Greetings, thanks, self-introductions, and questions about you — respond warmly. Do NOT escalate.\n'
  + '4. Truly unrelated topics (other apps, general trivia, jokes, weather elsewhere, coding) — gently steer back to FishPin. Do NOT escalate. (A user sharing their name, location, or that they fish is NOT off-topic — welcome it.)\n'
  + '5. HUMAN HAND-OFF — for a genuine support or business matter that needs a real person (billing or refund, "I paid but can\'t download", an app crash/bug, wrong GPS, account help, partnership / investor / sponsorship / press, or anything you genuinely cannot resolve from the facts): do NOT just deflect. FIRST reply warmly and helpfully — acknowledge their specific question, share anything relevant you do know (e.g. for investment/partnership, that FishPin works with cooperatives, LGUs, NGOs and sponsors), and let them know you are connecting them with the FishPin team and that they can reach us at ' + cfg.supportContact + '. THEN add a final line containing ONLY the marker [[HANDOFF]] — this marker line is removed before the user sees it, so never explain it.\n'
  + '6. Do not mention the word "context" or say you are reading from documents.\n'
  + '7. When it fits naturally, invite the user to download FishPin on Google Play.\n'
  + '8. Reply in the user\'s language (English or Filipino/Tagalog), matching how they wrote.';

const sys = persona + memoryNote + style + rules;

// ---- Recent verbatim turns (the rolling summary covers older history) ----
let history = Array.isArray(prep.history) ? prep.history.slice() : [];
while (history.length && history[0].role !== 'user') history.shift(); // Gemini needs a user-first turn
const historyContents = history.map((t) => ({
  role: t.role === 'model' ? 'model' : 'user',
  parts: [{ text: String(t.text || '') }],
}));

const chatBody = {
  systemInstruction: { parts: [{ text: sys }] },
  contents: [
    ...historyContents,
    { role: 'user', parts: [{ text: 'CONTEXT (FishPin facts you may use):\n' + (context || '(no relevant information found)') + '\n\nUSER MESSAGE: ' + message }] },
  ],
  generationConfig: {
    temperature: Number(cfg.chatTemperature || 0.55),
    topP: 0.95,
    maxOutputTokens: 700,
  },
};

return [{ json: { message, sessionId: prep.sessionId, score: Number(score.toFixed(3)), sources, chatBody } }];

// ============================================================================
// Decide — Code node (no credentials). Parses Gemini's answer; escalates to a
// human when the model said ESCALATE, returned nothing, or retrieval was weak.
// ============================================================================

const cfg = $('Config').first().json;
const ret = $('Retrieve').first().json;
const chat = $json;

let answer = '';
try {
  answer = chat.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
} catch (e) {
  answer = '';
}

// Escalation is INTENT-based. The model writes a warm, contextual reply and appends
// a [[HANDOFF]] marker line when a human should follow up — we strip the marker but
// KEEP the helpful reply, so the customer is answered first, never cold-deflected.
// Bare "ESCALATE" (legacy) or an empty answer falls back to a friendly default.
const HANDOFF_RE = /\[\[\s*hand\s*-?\s*off\s*\]\]/gi;
const norm = answer.toUpperCase().replace(/[^A-Z]/g, '');
let escalate = false;

if (HANDOFF_RE.test(answer)) {
  escalate = true;
  answer = answer.replace(HANDOFF_RE, '').replace(/\n{3,}/g, '\n\n').trim();
}

if (!answer || norm === 'ESCALATE') {
  escalate = true;
  answer = 'Thanks for your question! I want to make sure you get an accurate answer, so I\'ve passed this to the '
    + cfg.companyName + ' team. You can also reach us anytime at ' + cfg.supportContact + ' and we\'ll be glad to help.';
}

// Safety net: if we're handing off but the reply didn't say how to reach us, add it.
if (escalate && answer && !answer.includes('@') && cfg.supportContact) {
  answer += '\n\nYou can also reach our team directly at ' + cfg.supportContact + '.';
}

// ---- Conversation memory: persist this exchange for the session ----
// Best-effort; never let a memory write break the reply.
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const sess = sd.sessions[ret.sessionId] || { turns: [], summary: '' };
  sess.turns = sess.turns || [];
  sess.turns.push({ role: 'user', text: ret.message });
  sess.turns.push({ role: 'model', text: answer });
  // Hard safety cap; the post-response summarizer folds older turns into a
  // rolling summary so durable facts survive even very long conversations.
  const maxTurns = Number(cfg.memoryMaxTurns || 24);
  if (sess.turns.length > maxTurns) sess.turns = sess.turns.slice(-maxTurns);
  sess.updated = Date.now();
  sd.sessions[ret.sessionId] = sess;
  // Cap total stored sessions (prune oldest) so static data can't grow forever.
  const keys = Object.keys(sd.sessions);
  if (keys.length > 500) {
    keys.sort((a, b) => (sd.sessions[a].updated || 0) - (sd.sessions[b].updated || 0));
    for (let i = 0; i < keys.length - 500; i++) delete sd.sessions[keys[i]];
  }
} catch (e) {
  /* memory is best-effort */
}

return [{ json: {
  reply: answer,
  escalate,
  score: ret.score,
  sources: ret.sources,
  message: ret.message,
  sessionId: ret.sessionId,
} }];

// ============================================================================
// Memory Maintenance — Code node (no credentials). Runs AFTER the reply is sent.
// If the verbatim turn buffer has grown past the summarize threshold, it builds
// a prompt to fold the older turns into a rolling MEMORY NOTE (durable facts).
// Outputs { skip:true } when no summarization is needed.
// ============================================================================

const cfg = $('Config').first().json;
const ret = $('Decide').first().json;
const sid = ret.sessionId;

let out = { skip: true, sessionId: sid };
try {
  const sd = $getWorkflowStaticData('global');
  sd.sessions = sd.sessions || {};
  const sess = sd.sessions[sid] || { turns: [], summary: '' };
  const turns = sess.turns || [];

  const summarizeAt = Number(cfg.memorySummarizeAt || 16);
  const keep = Number(cfg.memoryKeep || 12);

  if (turns.length > summarizeAt) {
    const overflow = turns.slice(0, turns.length - keep); // older turns to fold in
    const convoText = overflow
      .map((t) => (t.role === 'user' ? 'User: ' : 'Assistant: ') + String(t.text || ''))
      .join('\n');

    const prompt = 'You maintain a concise running MEMORY NOTE for an ongoing customer-support chat for the FishPin app. '
      + 'Rewrite the memory note so it captures the durable facts worth remembering about THIS user and conversation: '
      + 'their name, location, boat or role, what they have asked about, their concerns or sentiment, and anything you promised or recommended. '
      + 'Be factual and third-person, no fluff, under 150 words. Merge the existing note with the new lines; drop nothing important.\n\n'
      + 'EXISTING MEMORY NOTE:\n' + (sess.summary || '(none yet)') + '\n\n'
      + 'NEW CONVERSATION LINES TO FOLD IN:\n' + convoText + '\n\nUPDATED MEMORY NOTE:';

    out = {
      skip: false,
      sessionId: sid,
      summaryBody: {
        contents: [{ role: 'user', parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.2, maxOutputTokens: 320 },
      },
    };
  }
} catch (e) {
  out = { skip: true, sessionId: sid, error: String((e && e.message) || e) };
}

return [{ json: out }];

// ============================================================================
// Apply Summary — Code node (no credentials). Runs after the summarizer LLM call.
// Writes the updated MEMORY NOTE and trims the verbatim turn buffer to the last
// `memoryKeep` turns. Best-effort; never throws.
// ============================================================================

const cfg = $('Config').first().json;
const mm = $('Memory Maintenance').first().json;
const sid = mm.sessionId;
const chat = $json; // Summarize response

let newSummary = '';
try {
  newSummary = chat.candidates[0].content.parts.map((p) => p.text || '').join('').trim();
} catch (e) {
  newSummary = '';
}

try {
  if (newSummary) {
    const sd = $getWorkflowStaticData('global');
    sd.sessions = sd.sessions || {};
    const sess = sd.sessions[sid];
    if (sess) {
      const keep = Number(cfg.memoryKeep || 12);
      sess.summary = newSummary.slice(0, 1500);
      sess.turns = (sess.turns || []).slice(-keep);
      sess.updated = Date.now();
      sd.sessions[sid] = sess;
    }
  }
} catch (e) {
  /* best-effort */
}

return [{ json: { ok: true, sessionId: sid, summaryUpdated: Boolean(newSummary) } }];
